// TypeScript Version: 4.1

import Uint64 = require( '@stdlib/number/uint64/ctor' );


/**
* Parses a string as an unsigned 64-bit integer.
*
* @param str - string representation of a nonnegative integer
* @throws must provide a string encoding a nonnegative integer
* @returns unsigned 64-bit integer
*
* @example
* var v = parseUint64( '5' );
* // returns <Uint64>
*/
declare function parseUint64( str: string ): Uint64;


// EXPORTS //

export = parseUint64;
